import { useEffect, useRef } from "react";

export default function SunriseBadge({ onReady }) {
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    const handleLoad = () => {
      const player = el.contentDocument?.getElementById("kl-svg")?.player;
      if (player) player.ready((p) => onReady?.(p));
    };
    el.addEventListener("load", handleLoad);
    return () => {
      el.removeEventListener("load", handleLoad);
      el.contentDocument?.getElementById("kl-svg")?.player?.destruct();
    };
  }, [onReady]);

  return (
    <object ref={ref} type="image/svg+xml" data="/sunrise-badge.svg" aria-label="Sunrise badge"
      style={{ width: "100%", maxWidth: 320 }} />
  );
}

// Usage: <SunriseBadge onReady={(player) => player.play()} />

