// sunrisebadge.component.ts
import { Component, ElementRef, OnDestroy, ViewChild } from "@angular/core";

@Component({
  selector: "app-sunrise-badge",
  standalone: true,
  template: `<object #anim type="image/svg+xml" data="assets/sunrise-badge.svg" aria-label="Sunrise badge"
    style="width:100%;max-width:320px" (load)="onLoad()"></object>`,
})
export class SunriseBadgeComponent implements OnDestroy {
  @ViewChild("anim") anim!: ElementRef<HTMLObjectElement>;
  player: any;

  onLoad() {
    this.player = this.anim.nativeElement.contentDocument?.getElementById("kl-svg")?.player;
    this.player?.ready((p: any) => p.on("end", () => console.log("finished")));
  }

  ngOnDestroy() { this.player?.destruct(); }
}

