// Get the player (inline SVG, or from an <object>'s contentDocument)
const player = document.getElementById("kl-svg").player;   // also .svgatorPlayer

// Methods (all chainable)
player.play();            // play from the current point; restarts if it has ended
player.pause();
player.toggle();          // alias: togglePlay()
player.restart();
player.reverse();         // flip direction and play
player.rollback();        // play backwards to the start, then stop
player.stop();            // stop and jump to the first frame
player.seek(50);          // jump to 50%
player.seekTo(1200);      // jump to 1200 ms
player.seekBy(-250);      // move 250 ms back
player.set("speed", 2);   // speed, fps (1–100), iterations (0 = infinite),
                          // direction (1 | -1), alternate (bool), fill (1 | -1)
player.ready((p) => {});  // runs once the player is ready
player.destruct();        // detach the player and its listeners

// Events: play, pause, restart, reverse, stop, end, keyframe
player.on("end", (offsetMs) => console.log("ended at", offsetMs));
player.on("keyframe", (offsetMs) => { /* every drawn frame */ });
player.off("end");

// Read-only state
player.currentTime   // ms
player.duration      // ms, one loop
player.totalTime     // ms, all iterations
player.state         // "playing" | "paused" | "ended" | "rollback"
player.isPlaying, player.isReversed, player.isRollingBack, player.hasEnded,
player.isInfinite, player.isAlternate, player.isBackwards,
player.speed, player.fps, player.direction, player.fill, player.iterations

